def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release (everything after '-')
        if '-' in version_part:
            base_part, prerelease = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                # Check if all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        # Return tuple for sorting:
        # - (major, minor, patch) for numeric comparison
        # - Empty list sorts before non-empty (no prerelease before prerelease)
        # - Prerelease identifiers with their type markers
        if not prerelease_identifiers:
            # No pre-release: sorts after any pre-release of same version
            return (major, minor, patch, 1, [])
        else:
            # Has pre-release: sorts before any non-pre-release of same version
            return (major, minor, patch, 0, prerelease_identifiers)

    # Use stable sort (maintain input order for equal elements)
    return sorted(versions, key=compare_key)

